UPDATE scholarships SET title = $$IIT Kharagpur - Institute Scholarships & Freeships are domestic support schemes, not for international applicants (retired)$$, provider = $$Indian Institute of Technology Kharagpur$$, country = $$India$$, coverage_type = $$Unspecified$$, amount_usd_value = 0, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, deadline = $$Retired - the schemes this record named (Merit-cum-Means institute scholarships and tuition-free institute freeships) belong to IIT Kharagpur's domestic undergraduate support system for the JEE-admitted cohort; there is no application round for international applicants. International students should use the Office of International Relations scholarship menu instead (see description).$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[]$$, recurrence = $$none$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's", "Master's", "PhD"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["RETIRED - domestic scope only: students admitted to IIT Kharagpur's BTech(Hons)/Dual Degree/BArch/Integrated MSc/BS programmes under the Indian (JEE) admission system, means-tested on Government of India family-income criteria"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$RETIRED in Pass 119 (2026-10-28) after first-hand verification. The "Institute Scholarships & Freeships" named in this record's old title are real, but they are IIT Kharagpur's DOMESTIC undergraduate support system, not an offer to international applicants: the institute's fetched scholarships page (iitkgp.ac.in/scholarships) sets out Merit-Cum-Means (MCM) scholarships for students admitted to the BTech(Hons), Dual Degree, BArch, Integrated MSc and BS programmes (SC/ST students are routed to State Post-Matric scholarships instead), capped at 25% of each admitted cohort, carrying exemption from the institute tuition fee, paid for 12 months (July-June), with a fresh-entrant merit bar of 60% in the JEE Advanced qualifying examination, renewal at GPA 7.00+, and a means test at the Government of India annual family-income ceiling evidenced by Indian income certificates/income-tax returns; a further 10% who meet the means but not the merit criterion receive tuition-free freeships. None of this is an application route for a foreign applicant. IIT Kharagpur's Office of International Relations publishes a separate scholarships menu for international students (fetched): the Guru Krupa Foundation (GKF) Postgraduate Scholarship for International Students (a real named award - verified in this pass and queued to be added as its own record), ADSIP (a full scholarship restricted to SAARC nationals) and SGRIP (short visits for foreign faculty/postdocs, not a degree scholarship). This row is retired rather than re-anchored because its title identified the domestic family; the separate international scheme will be added as its own record.$$ , requirements = $$Do not apply on the basis of this record - it is retired. The Merit-Cum-Means scholarships and institute freeships it named are awarded inside IIT Kharagpur's domestic undergraduate system (JEE-admitted cohorts; Government of India family-income means test with Indian income documents; 60% JEE-qualifying-exam merit bar for fresh entrants; renewal GPA 7.00). International students at IIT Kharagpur should instead consult the Office of International Relations scholarships index (international.iitkgp.ac.in/scholarships/): the Guru Krupa Foundation Postgraduate Scholarship for International Students (for enrolled self-funded international postgraduates), ADSIP (SAARC nationals only) and SGRIP (visiting foreign faculty/postdocs).$$ , website_url = $$https://www.iitkgp.ac.in/scholarships$$, source_url = $$https://www.iitkgp.ac.in/scholarships$$, application_url = $$https://www.iitkgp.ac.in/scholarships$$, funding_type = $$RETIRED - domestic institute support: Merit-cum-Means scholarships (max 25% of admitted UG/Dual cohort; tuition-fee exemption; 12-month payments; GoI means test) and 10% tuition-free institute freeships, for the JEE-admitted cohort$$, tuition_coverage = $$RETIRED - as fetched, MCM holders are exempted from the institute tuition fee (other prescribed fees still payable) and a further 10% receive tuition-free freeships; both are domestic-cohort schemes.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = NULL, english_requirements = $$Not applicable - retired record (domestic support schemes).$$ , required_documents = $$[]$$, application_status = $$closed$$, verification_status = $$verified$$, source_reliability = 9, is_active = false, university_id = 316, notes = $$PASS 119 RETIREMENT 2026-10-28 (India cluster): first-hand fetched evidence - IIT KGP scholarships page (iitkgp.ac.in/scholarships, new source 3123: MCM/freeship rules for the JEE-admitted UG/Dual cohort, GoI family-income means test with Indian income documents, SC/ST routed to State Post-Matric) and the IR Office scholarships index + GKF/ADSIP/SGRIP pages (fetched). The record's title identified the domestic family, so per catalogue discipline it is RETIRED as domestic-only rather than identity-swapped: the verified international scheme (Guru Krupa Foundation Postgraduate Scholarship for International Students - up to INR 25,000/month for enrolled self-funded international postgraduates with CGPA >= 8.5, annual January IR-office call, 1-year awards) is queued to be ADDED as its own new record in Batch 26; ADSIP is SAARC-only (Uzbekistan out of scope) and SGRIP covers visiting faculty/postdocs. Prior history: importer USD 12,000 + annual Aug-31 deadline already removed 2026-10-26 when the row became an honest non-verified placeholder; university_id 316 (IIT Kharagpur catalogue row) now set for correct attribution. Root source link 2541 retained for audit; (397, 3123) added.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 397;

